def is_nested(string):
    depth = 0
    max_depth = 0
    for char in string:
        if char == '[':
            depth += 1
            max_depth = max(max_depth, depth)
        elif char == ']':
            if depth == 0:
                return False
            depth -= 1
    return max_depth >= 2 and depth == 0
